-- Généré par scripts/sig/nour/poi-osm-extraire.py — ne pas éditer à la main.
-- Source : OpenStreetMap (ODbL). L'attribution est obligatoire dès l'affichage.
DROP TABLE IF EXISTS nour.poi_osm CASCADE;
CREATE TABLE nour.poi_osm (
  osm_type      text NOT NULL,
  osm_id        bigint NOT NULL,
  nom           text,
  categorie     text NOT NULL,
  sous_categorie text NOT NULL,
  tag_source    text NOT NULL,
  geom          geometry(Point,4326) NOT NULL,
  PRIMARY KEY (osm_type, osm_id)
);
CREATE INDEX poi_osm_geom_idx ON nour.poi_osm USING GIST (geom);
CREATE INDEX poi_osm_categorie_idx ON nour.poi_osm (categorie);
